import{_ as o,o as t,c,a4 as d}from"./chunks/framework.DCsBdTIw.js";const m=JSON.parse(`{"title":"Toolchain Structure","description":"clang locates each target's sysroot, headers, runtimes and linker through a plain-text config file in bin/ rather than defaults compiled into the compiler.","frontmatter":{"head":[["meta",{"property":"og:title","content":"Toolchain Structure | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/design/toolchain"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/design/toolchain"}],["meta",{"name":"twitter:card","content":"summary"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/design/toolchain"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/design/toolchain"}],["meta",{"property":"og:description","content":"clang locates each target's sysroot, headers, runtimes and linker through a plain-text config file in bin/ rather than defaults compiled into the compiler."}]]},"headers":[],"relativePath":"xclang/design/toolchain.md","filePath":"en/xclang/design/toolchain.md","lastUpdated":1795366604000}`),a={name:"xclang/design/toolchain.md"};function l(i,e,n,s,r,h){return t(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="toolchain-structure" tabindex="-1">Toolchain Structure <a class="header-anchor" href="#toolchain-structure" aria-label="Permalink to &quot;Toolchain Structure&quot;">​</a></h1><p><code>clang</code> locates each target&#39;s sysroot, headers, runtimes and linker through a plain-text config file in <code>bin/</code> rather than defaults compiled into the compiler. <code>clang</code>, <code>lld</code> and most binary tools share one multicall executable (<code>llvm</code>), and the sysroots and shared headers are plain directories without symbolic links on Windows or in the Linux sysroots. Passing <code>--target=&lt;triple&gt;</code> is therefore the whole difference between a native and a cross build, <code>-stdlib=platform</code> switches to the platform&#39;s C++ library, and <code>--no-default-config</code> restores a bare upstream <code>clang</code> (<a href="./../guide/cross-compiling#how-clang-finds-a-target-s-files">cross-compiling</a>, <a href="./../reference/layout">archive layout</a>).</p><h2 id="a-config-file-per-target" tabindex="-1">A Config File per Target <a class="header-anchor" href="#a-config-file-per-target" aria-label="Permalink to &quot;A Config File per Target&quot;">​</a></h2><p>When compiling or linking for a target, <code>clang</code> searches <code>bin/</code> next to its own executable for <code>&lt;triple&gt;.cfg</code> (<code>clang-cl</code> searches for <code>&lt;triple&gt;-clang-cl.cfg</code>) and prepends the file&#39;s flags to the command line. For <code>--target=aarch64-w64-mingw32</code>, <code>clang</code> normalizes the triple and reads <code>aarch64-w64-windows-gnu.cfg</code>. <code>toolchain/common.ts</code> writes a config file into <code>bin/</code> for every accepted spelling of each target:</p><table tabindex="0"><thead><tr><th>target</th><th>config files in <code>bin/</code></th></tr></thead><tbody><tr><td>Linux (glibc)</td><td><code>&lt;arch&gt;-unknown-linux-gnu.cfg</code>, <code>&lt;arch&gt;-pc-linux-gnu.cfg</code></td></tr><tr><td>Linux (musl)</td><td><code>&lt;arch&gt;-unknown-linux-musl.cfg</code>, <code>&lt;arch&gt;-pc-linux-musl.cfg</code></td></tr><tr><td>Windows (MinGW)</td><td><code>&lt;arch&gt;-w64-windows-gnu.cfg</code>, <code>&lt;arch&gt;-pc-windows-gnu.cfg</code></td></tr><tr><td>macOS</td><td><code>&lt;arch&gt;-apple-darwin.cfg</code>, <code>&lt;arch&gt;-apple-macos.cfg</code>, <code>&lt;arch&gt;-apple-macosx.cfg</code></td></tr><tr><td>Windows (MSVC)</td><td><code>&lt;arch&gt;-pc-windows-msvc.cfg</code>, <code>&lt;arch&gt;-unknown-windows-msvc.cfg</code>, and for <code>clang-cl</code> <code>&lt;spelling&gt;-clang-cl.cfg</code></td></tr></tbody></table><p><code>&lt;arch&gt;</code> is <code>x86_64</code>, or for 64-bit Arm both <code>aarch64</code> and <code>arm64</code>. Because <code>compiler-rt</code> installs its libraries under the canonical <code>&lt;arch&gt;-unknown-linux-*</code> and <code>&lt;arch&gt;-w64-windows-gnu</code> directory names, <a href="./../reference/patches">patch 0013</a> maps the <code>-pc-</code> and <code>arm64-</code> spellings of the Linux and MinGW targets back to that runtime directory.</p><p>Each target config file sets the following options (<a href="https://github.com/clice-io/xclang/tree/main/toolchain/config" target="_blank" rel="noreferrer"><code>toolchain/config/</code></a>):</p><table tabindex="0"><thead><tr><th>target</th><th>options in <code>&lt;spelling&gt;.cfg</code></th></tr></thead><tbody><tr><td>Linux (glibc)</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>, <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-static-libstdc++ -static-libgcc</code>, <code>-fuse-ld=lld</code></td></tr><tr><td>Linux (musl)</td><td>the same with <code>-static</code> in place of <code>-static-libstdc++ -static-libgcc</code>, linking <code>musl</code> statically as well (<a href="./../guide/cross-compiling#musl-targets">musl targets</a>)</td></tr><tr><td>Windows (MinGW)</td><td><code>--sysroot=&lt;CFGDIR&gt;/../&lt;triple&gt;</code>, <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-idirafter &lt;CFGDIR&gt;/../mingw-w64/include</code>, <code>-rtlib=compiler-rt -unwindlib=libunwind -stdlib=libc++</code>, <code>-fuse-ld=lld</code> (the sysroot contains static libraries only)</td></tr><tr><td>macOS</td><td>on Linux and Windows hosts <code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code> (on macOS hosts Xcode&#39;s SDK); <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code>; <code>-stdlib++-isystem</code> for the target&#39;s <code>__config_site</code> and shared <code>libc++</code> headers, <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> (placing <code>libc++.a</code> ahead of the SDK&#39;s <code>libc++.tbd</code>), and <code>-B&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> for <code>libc++.modules.json</code> (<a href="./macos">macOS</a>)</td></tr><tr><td>Windows (MSVC)</td><td>on Linux and macOS hosts <code>-Xmicrosoft-windows-sys-root &lt;CFGDIR&gt;/../sdk/windows</code> (<code>/winsysroot</code> in <code>clang-cl</code>); <code>@&lt;triple&gt;-sdk.cfg</code> (<code>@&lt;triple&gt;-clang-cl-sdk.cfg</code>), rewritten by <code>xclang sdk</code> to include the active SDK&#39;s version config; <code>-fuse-ld=lld</code>; object directives for <code>clang_rt.builtins-&lt;arch&gt;.lib</code> and the hybrid CRT (<code>--linker-option=/nodefaultlib:libucrt.lib</code>, <code>--dependent-lib=ucrt.lib</code>); <code>-D_STATIC_INLINE_UCRT_FUNCTIONS=0</code>; and <code>-stdlib++-isystem</code> (<code>/clang:-stdlib++-isystem</code> in <code>clang-cl</code>, silenced on C compiles by <a href="./../reference/patches">patch 0011</a>) for <code>libc++</code> (<a href="./windows#config-files-and-object-directives">Windows</a>)</td></tr></tbody></table><p><code>&lt;CFGDIR&gt;</code> expands to <code>bin/</code>, so the toolchain works from any unpacked directory without modification. Because <code>clang</code> loads the config file for the host&#39;s default target as well, a native <code>clang++ main.cpp</code> on Linux compiles against the bundled glibc 2.17 sysroot and links <code>libc++</code> statically.</p><p>Two additional config-file rules avoid surprises in <code>clang-cl</code> and Bazel:</p><ul><li><strong><code>clang-cl</code> defaults to the host architecture&#39;s MSVC target.</strong> When run without <code>--target</code>, <code>clang-cl</code> searches for <code>&lt;default-target&gt;-clang-cl.cfg</code> and <code>&lt;default-target&gt;.cfg</code> before switching to an MSVC triple. <code>toolchain/common.ts</code> writes the MSVC <code>clang-cl</code> config of <code>&lt;arch&gt;</code> to <code>&lt;spelling&gt;-clang-cl.cfg</code> (and <code>&lt;spelling&gt;-clang-cl-system.cfg</code>) for every target spelling, so a plain <code>clang-cl</code> builds for <code>&lt;arch&gt;-pc-windows-msvc</code> instead of reading the host target&#39;s GNU flags.</li><li><strong>Bazel rewrites the config files with relative paths.</strong> <code>clang</code> expands <code>&lt;CFGDIR&gt;</code> to an absolute path, which enters <code>.d</code> dependency files and breaks cross-machine action caching. The Bazel module writes copies of the config files under <code>cfg/</code> with paths relative to the execution root and passes <code>--no-default-config --config=&lt;file&gt;</code> (<a href="./bazel-module#no-absolute-paths">no absolute paths</a>).</li></ul><h3 id="the-platform-s-c-library" tabindex="-1">The Platform&#39;s C++ Library <a class="header-anchor" href="#the-platform-s-c-library" aria-label="Permalink to &quot;The Platform&#39;s C++ Library&quot;">​</a></h3><p>Every <code>&lt;spelling&gt;.cfg</code> has a companion <code>&lt;spelling&gt;-system.cfg</code> (and <code>&lt;spelling&gt;-clang-cl-system.cfg</code>). Passing any <code>-stdlib=</code> value other than <code>libc++</code> (<code>-stdlib=platform</code> or <code>-stdlib=libstdc++</code>; in <code>clang-cl</code>, <code>/clang:-stdlib=platform</code>) selects <code>&lt;spelling&gt;-system.cfg</code> in place of <code>&lt;spelling&gt;.cfg</code> (<a href="./../reference/patches">patch 0018</a>, <a href="./../guide/cross-compiling#the-platform-s-c-library">cross-compiling</a>):</p><table tabindex="0"><thead><tr><th>target</th><th>options in <code>&lt;spelling&gt;-system.cfg</code></th></tr></thead><tbody><tr><td>Linux (glibc), Linux (musl), Windows (MinGW)</td><td><code>-fuse-ld=lld</code> only; the C and C++ libraries come from the host, a distribution&#39;s cross packages, or <code>--sysroot</code></td></tr><tr><td>macOS</td><td>the SDK (<code>-isysroot &lt;CFGDIR&gt;/../sdk/macos</code> on Linux and Windows hosts), <code>-mmacos-version-min=13.0</code>, <code>-fuse-ld=lld</code>, linking the SDK&#39;s <code>libc++.tbd</code></td></tr><tr><td>Windows (MSVC)</td><td>the MSVC target config without <code>-stdlib++-isystem</code>, using Microsoft&#39;s STL from the fetched SDK or Visual Studio</td></tr></tbody></table><p>Switching config files is necessary because flags in <code>&lt;spelling&gt;.cfg</code> cannot be undone later on the command line: <code>-stdlib++-isystem</code> adds <code>libc++</code> headers regardless of <code>-stdlib=</code>, <code>-L&lt;CFGDIR&gt;/../&lt;triple&gt;/lib</code> on macOS puts <code>libc++.a</code> before the SDK&#39;s <code>libc++.tbd</code>, and the bundled Linux and MinGW sysroots do not carry <code>libstdc++</code>.</p><h3 id="why-not-built-in-defaults" tabindex="-1">Why Not Built-In Defaults <a class="header-anchor" href="#why-not-built-in-defaults" aria-label="Permalink to &quot;Why Not Built-In Defaults&quot;">​</a></h3><p>LLVM can compile defaults for the C++ library, compiler runtime, unwinder and linker directly into the driver (<code>CLANG_DEFAULT_CXX_STDLIB</code>, <code>CLANG_DEFAULT_RTLIB</code>, <code>CLANG_DEFAULT_UNWINDLIB</code>, <code>CLANG_DEFAULT_LINKER</code>), as xclang 23.1.2.1 did. Those settings are compiled into <code>clangDriver</code>, which is also part of <code>libclang</code>.</p><p>Tools built on <code>libclang</code> (such as clice) run <code>clangDriver</code> to compute include paths from <code>compile_commands.json</code> entries for other compilers. With defaults compiled into <code>clangDriver</code>, a <code>g++</code> command in a compilation database received xclang&#39;s <code>libc++</code> include paths instead of <code>libstdc++</code>&#39;s.</p><p>Keeping those <code>CLANG_DEFAULT_*</code> variables unset in <code>toolchain/cmake/caches/clang.cmake</code> and placing the defaults in <code>bin/*.cfg</code> separates the two: <code>bin/clang</code> reads <code>bin/&lt;triple&gt;.cfg</code>, while <code>clangDriver</code> linked inside a <code>libclang</code> tool has no <code>bin/*.cfg</code> and behaves like upstream <code>clang</code>.</p><h3 id="the-bare-compiler" tabindex="-1">The Bare Compiler <a class="header-anchor" href="#the-bare-compiler" aria-label="Permalink to &quot;The Bare Compiler&quot;">​</a></h3><p>Passing <code>--no-default-config</code> tells <code>clang</code> to ignore <code>bin/&lt;triple&gt;.cfg</code>. <code>clang</code> then searches the host system&#39;s headers and libraries and invokes the system linker, just as an unconfigured upstream build does (<code>toolchain/sysroot.ts</code> and <code>toolchain/runtimes.ts</code> use <code>--no-default-config</code> when building the sysroots and <code>libc++</code> themselves).</p><h2 id="one-program" tabindex="-1">One Program <a class="header-anchor" href="#one-program" aria-label="Permalink to &quot;One Program&quot;">​</a></h2><p><code>toolchain/cmake/caches/clang.cmake</code> sets <code>LLVM_TOOL_LLVM_DRIVER_BUILD=ON</code>, which builds <code>clang</code>, <code>clang-scan-deps</code>, <code>lld</code> and most binary tools (<code>llvm-ar</code>, <code>llvm-ranlib</code>, <code>llvm-lib</code>, <code>llvm-dlltool</code>, <code>llvm-nm</code>, <code>llvm-objcopy</code>, <code>llvm-strip</code>, <code>llvm-install-name-tool</code>, <code>llvm-objdump</code>, <code>llvm-readobj</code>, <code>llvm-rc</code>, <code>llvm-windres</code>, <code>llvm-symbolizer</code>, <code>dsymutil</code>, <code>llvm-gsymutil</code>, <code>llvm-libtool-darwin</code>, <code>llvm-lipo</code>, ...) into one multicall executable, <code>bin/llvm</code> (<code>bin/llvm.exe</code> on Windows).</p><p>Instead of each binary carrying a separate copy of the LLVM libraries, every tool name in <code>bin/</code> is a symbolic link to <code>llvm</code> on Linux and macOS, or a small launcher compiled from <a href="https://github.com/clice-io/xclang/blob/main/toolchain/launcher/alias.c" target="_blank" rel="noreferrer"><code>toolchain/launcher/alias.c</code></a> on Windows that starts <code>llvm.exe &lt;tool-name&gt; &lt;arguments&gt;</code> inside a kill-on-close job object (<a href="./windows#the-launchers">the launchers</a>). Together with omitting glibc&#39;s <code>locale-archive</code>, linking with safe identical code folding (<code>-Wl,--icf=safe -Wl,-O2</code> on Linux and Windows), and compressing all host archives with <code>.tar.xz</code>, each host toolchain archive is about 100 MB (<a href="./../reference/releases#assets">releases</a>).</p><p>Linking the tools against a shared <code>libLLVM</code> (<code>LLVM_LINK_LLVM_DYLIB</code>) would also share code, but was rejected for compile speed: calls across a shared library boundary go through dynamic linker tables, and ThinLTO cannot inline or optimize across it.</p><p>Five tools that LLVM&#39;s multicall driver build does not include are compiled as standalone binaries in <code>bin/</code>: <code>llvm-profdata</code>, <code>llvm-cov</code>, <code>llvm-dwarfdump</code>, <code>llvm-strings</code> and <code>FileCheck</code>.</p><h3 id="what-prints" tabindex="-1">What <code>-###</code> Prints <a class="header-anchor" href="#what-prints" aria-label="Permalink to &quot;What `-###` Prints&quot;">​</a></h3><p>Because <code>clang</code> is dispatched by the multicall <code>llvm</code> binary, <code>clang -###</code> prints its <code>-cc1</code> command with <code>llvm</code> as the program and <code>&quot;clang&quot;</code> before <code>&quot;-cc1&quot;</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;/path/xclang/bin/llvm&quot; &quot;clang&quot; &quot;-cc1&quot; ...</span></span></code></pre></div><p>Tools that parse <code>clang -###</code> output must scan for <code>&quot;-cc1&quot;</code> rather than assuming <code>&quot;-cc1&quot;</code> is the first argument after the executable path.</p><h2 id="the-musl-hosts" tabindex="-1">The musl Hosts <a class="header-anchor" href="#the-musl-hosts" aria-label="Permalink to &quot;The musl Hosts&quot;">​</a></h2><p>The <code>x86_64-unknown-linux-musl</code> and <code>aarch64-unknown-linux-musl</code> toolchains are cross-compiled on Linux x64 for xclang&#39;s own <a href="./../guide/cross-compiling#musl-targets">musl targets</a>: <code>bin/llvm</code> and the other programs are static, with no program interpreter and no dynamic section, so they run on any Linux. Beyond that, their build differs from the glibc hosts&#39; in two flags, which <code>checkMusl</code> in <code>toolchain/toolchain.ts</code> checks in every program:</p><ul><li><strong>mimalloc in place of musl&#39;s <code>malloc</code></strong>: the programs link mimalloc 2.5.3&#39;s single object (<code>MI_OVERRIDE</code>). It also defines musl&#39;s internal <code>__libc_malloc</code> and <code>__libc_free</code>, so none of musl&#39;s allocator is linked.</li><li><strong>8 MiB thread stacks</strong> (<code>-Wl,-z,stack-size=8388608</code>): musl gives a thread 128 KiB of stack, and LLVM sets a thread&#39;s stack size only on Apple systems and AIX. <code>lld</code> runs its parallel work and ThinLTO&#39;s backends on such threads. Linked without the flag, every ThinLTO link in the benchmark below crashed in <code>lld</code>.</li></ul><p>Measured for 23.1.5.3 on GitHub&#39;s Linux x64 and arm64 runners against the glibc hosts&#39; toolchain of 23.1.5.2, built with the same profile and compiling for the same target, median of three runners (time relative to glibc, lower is faster; mimalloc 2.5.3 built for ARMv8.1 on arm64 there, the release&#39;s for the baseline). Compile times span the fmt, lua and <code>std</code> builds (<code>tests/bench</code>); the link is a small <code>libclang</code> tool linked with ThinLTO and no cache:</p><table tabindex="0"><thead><tr><th>allocator</th><th>compile, Linux x64</th><th>compile, Linux arm64</th><th>link, Linux x64</th><th>link, Linux arm64</th></tr></thead><tbody><tr><td>mimalloc 2.5.3</td><td>0.82–0.96</td><td>0.70–0.84</td><td>0.99</td><td>0.92</td></tr><tr><td>mimalloc 3.7.0</td><td>0.82–0.96</td><td>0.69–0.83</td><td>0.95</td><td>0.93</td></tr><tr><td>musl&#39;s <code>malloc</code> (mallocng)</td><td>0.84–1.22</td><td>0.83–1.24</td><td>1.43</td><td>2.68</td></tr><tr><td>snmalloc 0.7.6</td><td>0.92–1.06</td><td>0.78–0.97</td><td>0.95</td><td>0.88</td></tr><tr><td>jemalloc 5.4.0</td><td>0.76–1.05</td><td>0.79–0.99</td><td>0.95</td><td>0.89</td></tr></tbody></table><p>With either mimalloc, the link&#39;s peak memory is 0.69 to 0.78 of glibc&#39;s. On the frontend (<code>clang -fsyntax-only</code> over clang&#39;s Sema sources and abseil), 2.5.3 is as fast as 3.7.0, 0.89 to 0.90 of glibc&#39;s time on Linux x64 and 0.80 to 0.82 on arm64, with less memory: 1.03 to 1.16 times glibc&#39;s peak against 3.7.0&#39;s 1.11 to 1.24. 3.7.0 asks for transparent huge pages (<code>MADV_HUGEPAGE</code>) and purges only whole 2 MiB pages, and its speed comes from them: without them (<code>MIMALLOC_ALLOW_THP=0</code>) its peak memory is 0.98 to 1.11 times glibc&#39;s, and it takes 0.97 to 1.03 of glibc&#39;s time. Most of the lead over glibc is the allocator itself. In another run, the glibc hosts&#39; toolchain with mimalloc 3.7.0 preloaded (<code>LD_PRELOAD</code>) took 0.88 to 0.89 of its own time on the fmt and <code>std</code> builds on Linux x64 and 0.82 to 0.86 on arm64; the musl hosts&#39; took 0.88 to 0.91 and 0.81 to 0.83. The static executable adds a faster start, as it has none of the glibc build&#39;s 247,000 relocations: <code>clang --version</code> takes 4.2 ms on Linux x64 and 3.4 ms on arm64, against glibc&#39;s 8.5 and 7.9 ms, which makes lua&#39;s 34 small files up to 20% faster still. The glibc hosts&#39; profile serves the musl hosts as it serves every host (<a href="./pgo#one-profile-for-every-host">one profile for every host</a>).</p><p>The rest of musl is left as it is. In a <code>perf</code> profile of the fmt build, musl&#39;s string functions take 3.18% of <code>clang</code>&#39;s samples on Linux x64 and 1.61% on arm64, glibc&#39;s 2.12% and 1.17%. On Linux x64 that offsets what the static allocator saves (mimalloc 3.7.0: 1.63% of the samples, against 3.05% preloaded), and links, which copy and compare much, take 4 to 10% longer than the glibc build&#39;s with mimalloc. musl&#39;s <code>qsort</code> (smoothsort, which LLVM&#39;s <code>array_pod_sort</code> calls) takes under 0.1%, and no locale or <code>ctype</code> function reaches 0.05%. Neither <code>dlopen</code> nor DNS matters: no host&#39;s <code>clang</code> or <code>lld</code> loads plugins (<code>LLVM_ENABLE_PLUGINS</code> and <code>CLANG_PLUGIN_SUPPORT</code> are off) or reaches the network. One difference remains: a crash prints no stack trace on the musl hosts, because LLVM walks the stack only with glibc.</p><h2 id="plain-directories" tabindex="-1">Plain Directories <a class="header-anchor" href="#plain-directories" aria-label="Permalink to &quot;Plain Directories&quot;">​</a></h2><p>Each target&#39;s sysroot (<code>&lt;toolchain&gt;/&lt;triple&gt;/</code>) is a plain directory containing only what compiling and linking read: headers, startup files, C runtime libraries, <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code> and the <a href="./hermeticity#gcc-library-names">GCC stub archives</a>, while <code>compiler-rt</code> lives in <code>lib/clang/&lt;major&gt;/lib/</code> (<a href="./../reference/layout">archive layout</a>).</p><p>Headers that are identical across targets are stored once without symbolic links (<code>shareHeaders</code> in <code>toolchain/common.ts</code>): <code>libc++/include/c++/v1</code> for all targets, <code>libc++/include/&lt;normalized-triple&gt;/c++/v1</code> for each target&#39;s <code>__config_site</code> (and <code>cxxabi.h</code> on non-MSVC targets), and <code>mingw-w64/include</code> for both MinGW targets (<a href="./../reference/layout#shared-headers">shared headers</a>). <code>toolchain/package.ts</code> verifies that Windows toolchain archives contain no symbolic links and that no archive contains two paths differing only in case (<a href="./hermeticity#why-glibc-2-17">why glibc 2.17</a>).</p><p>Nothing in the sysroots or <code>compiler-rt</code> directory is specific to xclang&#39;s build of <code>clang</code>. Any upstream <code>clang</code> of the same major version can cross-compile against a target directory when given <code>--sysroot</code> and <code>-resource-dir</code>.</p>',41)])])}const u=o(a,[["render",l]]);export{m as __pageData,u as default};
